fn to_lowercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());
    
    for &c in str1.iter() {
        if c >= 'A' && c <= 'Z' {
            // Convert uppercase to lowercase
            result.push((c as u8 + 32) as char);
        } else {
            // Keep the character unchanged
            result.push(c);
        }
    }
    
    result
}